INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein WLAN-Router mit höherer Frequenz immer schneller?', 2, '[{"text": "Nein", "correct": true, "because": " Reichweite und Interferenzen spielen eine Rolle"}, {"text": "Ja", "correct": false, "because": "Geschwindigkeit hängt von mehreren Faktoren ab"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal eines WLAN-Routers ist für die Datenübertragung im 5-GHz-Band entscheidend?', 3, '[{"text": "Unterstützung von 802.11ac", "correct": true, "because": "Ermöglicht 5-GHz-Nutzung"}, {"text": "Anzahl der LAN-Ports", "correct": false, "because": "Nur für kabelgebundene Verbindungen"}, {"text": "Gehäusefarbe", "correct": false, "because": "Kein Einfluss auf Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein WLAN-Router mit mehr Antennen hat immer bessere Reichweite. b) Der Router verbindet verschiedene Netzwerke.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Reichweite hängt nicht nur von Antennen ab"}, {"text": "Nur b) stimmt", "correct": true, "because": "Router leitet zwischen Netzwerken"}, {"text": "Beides stimmt", "correct": false, "because": "Aussage a) ist nicht immer wahr"}, {"text": "Beides falsch", "correct": false, "because": "Aussage b) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Faktor solltest du bei der Auswahl eines WLAN-Routers für ein großes Büro priorisieren?', 4, '[{"text": "Reichweite und Signalstärke", "correct": true, "because": "Wichtig für viele Nutzer"}, {"text": "Anzahl der LEDs", "correct": false, "because": "Nur Statusanzeige"}, {"text": "Design des Gehäuses", "correct": false, "because": "Kein Einfluss auf Leistung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein WLAN-Router ohne Internetverbindung ein lokales Netzwerk bereitstellen?', 2, '[{"text": "Ja", "correct": true, "because": "Lokale Verbindungen sind unabhängig"}, {"text": "Nein", "correct": false, "because": "Internet ist nicht zwingend nötig"}]');
