('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein WLAN-Router mit mehr Antennen hat immer bessere Reichweite. b) Der Router verbindet verschiedene Netzwerke.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Reichweite hängt nicht nur von Antennen ab"}, {"text": "Nur b) stimmt", "correct": true, "because": "Router leitet zwischen Netzwerken"}, {"text": "Beides stimmt", "correct": false, "because": "Aussage a) ist nicht immer wahr"}, {"text": "Beides falsch", "correct": false, "because": "Aussage b) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Faktor solltest du bei der Auswahl eines WLAN-Routers für ein großes Büro priorisieren?', 4, '[{"text": "Reichweite und Signalstärke", "correct": true, "because": "Wichtig für viele Nutzer"}, {"text": "Anzahl der LEDs", "correct": false, "because": "Nur Statusanzeige"}, {"text": "Design des Gehäuses", "correct": false, "because": "Kein Einfluss auf Leistung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein WLAN-Router ohne Internetverbindung ein lokales Netzwerk bereitstellen?', 2, '[{"text": "Ja", "correct": true, "because": "Lokale Geräte können verbunden werden"}, {"text": "Nein", "correct": false, "because": "Internet ist nicht zwingend nötig"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Reichweite eines WLAN-Routers nur von der Antenne abhängig?', 2, '[{"text": "Nein", "correct": true, "because": "Frequenz und Umgebung beeinflussen ebenfalls"}, {"text": "Ja", "correct": false, "because": "Mehrere Faktoren spielen eine Rolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktion eines WLAN-Routers ist für die Verbindung zum Internet entscheidend?', 3, '[{"text": "WAN-Port", "correct": true, "because": "Verbindet zum Internetanbieter"}, {"text": "Anzahl der LEDs", "correct": false, "because": "Nur Statusanzeige"}, {"text": "Gewicht des Geräts", "correct": false, "because": "Kein Einfluss auf Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein WLAN-Router mit 2,4 GHz hat mehr Reichweite als 5 GHz. b) Ein Router kann nur ein Netzwerk verwalten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "2,4 GHz hat größere Reichweite"}, {"text": "Beides stimmt", "correct": false, "because": "Router kann mehrere Netzwerke"}, {"text": "Nur b) stimmt", "correct": false, "because": "5 GHz hat weniger Reichweite"}, {"text": "Beides falsch", "correct": false, "because": "Aussage a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Parameter solltest du bei einem WLAN-Router für ein Mehrfamilienhaus priorisieren?', 4, '[{"text": "Starke Signalstärke", "correct": true, "because": "Durchdringt Wände besser"}, {"text": "Anzahl der USB-Ports", "correct": false, "because": "Weniger relevant"}, {"text": "Farbe des Gehäuses", "correct": false, "because": "Kein Einfluss auf Leistung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein WLAN-Router ohne DHCP lokale IP-Adressen vergeben?', 2, '[{"text": "Nein", "correct": true, "because": "DHCP ist für IP-Vergabe nötig"}, {"text": "Ja", "correct": false, "because": "Manuelle Konfiguration wäre nötig"}]');
